-- Domains deliberately left out of a capacity assessment (domain id -> reason).
-- Left out of area and overall averages (src/lib/cca/engine.ts). Additive: one column with a default.
ALTER TABLE "cca_assessments" ADD COLUMN IF NOT EXISTS "not_assessed" jsonb NOT NULL DEFAULT '{}'::jsonb;

-- The domains a completed assessment covered. Domains added to a module later count as not assessed for it, so
-- new content never lowers a past result. Assessments completed before this column existed covered the domains
-- published at the time, listed here.
ALTER TABLE "cca_assessments" ADD COLUMN IF NOT EXISTS "domain_ids" jsonb;
UPDATE "cca_assessments" SET "domain_ids" = '["nat-gov-1", "nat-gov-2", "nat-gov-3", "nat-pfm-1", "nat-pfm-2", "nat-pfm-3", "nat-pfm-4", "nat-proc-1", "nat-proc-2", "nat-proc-3", "nat-hr-1", "nat-hr-2", "nat-hr-3", "nat-plan-1", "nat-plan-2", "nat-plan-3", "nat-svc-1", "nat-svc-2", "nat-svc-3", "nat-part-1", "nat-part-2", "nat-part-3", "nat-res-1", "nat-res-2", "nat-res-3"]'::jsonb WHERE "status" = 'complete' AND "domain_ids" IS NULL AND "module" = 'national';
